'use strict';

const UNITS = { ms: 1, s: 1000, m: 60000, h: 3600000, d: 86400000 };
const PART = /(\d+(?:\.\d+)?)\s*(ms|s|m|h|d)/gy;

/** See README.md. */
function parseDuration(text) {
  if (typeof text !== 'string') throw new TypeError('not a string');
  const s = text.trim().toLowerCase();
  if (!s) throw new TypeError('empty duration');
  let total = 0;
  let i = 0;
  while (i < s.length) {
    while (s[i] === ' ') i++;
    if (i >= s.length) break;
    PART.lastIndex = i;
    const m = PART.exec(s);
    if (!m) throw new TypeError(`bad duration: ${text}`);
    total += parseFloat(m[1]) * UNITS[m[2]];
    i = PART.lastIndex;
  }
  return total;
}

module.exports = { parseDuration };

'use strict';
const test = require('node:test');
const assert = require('node:assert');
const { parseDuration } = require('../duration.js');

test('examples', () => {
  assert.equal(parseDuration('1h30m'), 5400000);
  assert.throws(() => parseDuration('5y'), TypeError);
});
